SELECT customers.segment, customers.country, ROUND(AVG(web_events.duration_sec), 2) AS avg_duration_sec, ROUND(STDDEV(web_events.duration_sec), 2) AS stddev_duration_sec FROM web_events LEFT OUTER JOIN sessions ON web_events.session_id = sessions.id INNER JOIN customers ON sessions.customer_id = customers.id GROUP BY customers.segment, customers.country HAVING avg_duration_sec >= 36
